import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, random, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type EkgLineAnimationProps = Record<string, any>;

const EkgLineAnimation: React.FC<EkgLineAnimationProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  lineColor = "#00ffcc",
  durationInSeconds = 10,
  lineWidth = 4,
  spikeHeight = 200,
  spikeFrequency = 5,
  noiseAmplitude = 5,
  glowIntensity = 10,
}) => {
  // Although not using text, standardizing the loader prevents removal errors if extended later
  useFontLoader([]); 

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const totalFrames = durationInSeconds * fps;
  const safeBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Generate the path and spike locations deterministically
  const pathData = useMemo(() => {
    const points: [number, number][] = [];
    const step = 2; // Resolution of the line in pixels
    const baselineY = height / 2;
    
    // Determine spike locations using Remotion's random with a fixed seed
    // We want 'spikeFrequency' number of spikes distributed across the width
    const spikeLocations: number[] = [];
    // Leave some padding at start/end
    const padding = width * 0.1;
    const usableWidth = width - padding * 2;
    
    // Divide usable width into segments
    const segmentWidth = usableWidth / spikeFrequency;

    for (let i = 0; i < spikeFrequency; i++) {
      // Add some jitter to exact center of segment so it looks organic
      const segmentStart = padding + i * segmentWidth;
      const jitter = (random(`spike-loc-${i}`) - 0.5) * (segmentWidth * 0.6);
      spikeLocations.push(segmentStart + segmentWidth / 2 + jitter);
    }

    let totalLen = 0;
    let prevX = 0;
    let prevY = baselineY;

    for (let x = 0; x <= width; x += step) {
      let y = baselineY;

      // 1. Add subtle breathing noise (multiple sine waves for organic feel)
      // Low frequency, low amplitude
      const noise1 = Math.sin(x * 0.01) * noiseAmplitude;
      const noise2 = Math.sin(x * 0.035) * (noiseAmplitude * 0.5);
      y += noise1 + noise2;

      // 2. Add Spikes
      // Simple sharp impulse: Gaussian with very narrow width
      for (const spikeX of spikeLocations) {
        const dist = x - spikeX;
        // Check if we are close enough to calculate
        if (Math.abs(dist) < 100) { 
          // Gaussian function: A * exp(-(x-b)^2 / (2c^2))
          // To make it sharp (quick rise/fall), 'c' must be small.
          const spread = 8; // Lower = sharper
          const spikeY = -spikeHeight * Math.exp(-(dist * dist) / (2 * spread * spread));
          y += spikeY;
        }
      }

      points.push([x, y]);

      // Calculate distance for strokeDasharray
      if (x > 0) {
        const dx = x - prevX;
        const dy = y - prevY;
        totalLen += Math.sqrt(dx * dx + dy * dy);
      }
      prevX = x;
      prevY = y;
    }

    // Convert points to SVG Path command
    // Using L (Line) is sufficient for high resolution, C (Curve) is expensive to compute manually without library
    const d = `M ${points[0][0]} ${points[0][1]} ` + points.slice(1).map(p => `L ${p[0]} ${p[1]}`).join(" ");

    return { d, length: totalLen };
  }, [width, height, spikeFrequency, spikeHeight, noiseAmplitude]);

  // Animate the drawing of the line
  const progress = interpolate(frame, [0, totalFrames], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const dashOffset = interpolate(progress, [0, 1], [pathData.length, 0]);

  return (
    <AbsoluteFill style={{ backgroundColor: safeBgColor }}>
      <svg
        width={width}
        height={height}
        viewBox={`0 0 ${width} ${height}`}
        style={{
          overflow: "visible",
        }}
      >
        <defs>
            {/* Glow Filter */}
            <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                <feGaussianBlur stdDeviation={glowIntensity} result="coloredBlur" />
                <feMerge>
                    <feMergeNode in="coloredBlur" />
                    <feMergeNode in="SourceGraphic" />
                </feMerge>
            </filter>
        </defs>

        {/* The Line */}
        <path
          d={pathData.d}
          stroke={lineColor}
          strokeWidth={lineWidth}
          fill="none"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeDasharray={pathData.length}
          strokeDashoffset={dashOffset}
          style={{
             filter: glowIntensity > 0 ? "url(#glow)" : "none",
          }}
        />
        
        {/* Optional: Leading dot for the "drawing" tip effect */}
        {progress < 1 && progress > 0 && (
           <circle 
             r={lineWidth * 1.5}
             fill={lineColor}
             style={{
                offsetPath: `path('${pathData.d}')`,
                offsetDistance: `${progress * 100}%`,
                filter: glowIntensity > 0 ? "url(#glow)" : "none",
             }}
           />
        )}
      </svg>
    </AbsoluteFill>
  );
};

export default EkgLineAnimation;